func TestTaskCreate(t *testing.T) {
	store, _ := newClockStore()
	h := NewHandler(store)
	mustRegister(t, h, "dev-1")

	task := createTask(t, h, "dev-1", taskBody("req-1", 30), http.StatusCreated)
	if task.ID != 1 || task.Status != "pending" || task.DurationSeconds != 30 || task.Attempts != 0 {
		t.Fatalf("unexpected task: %+v", task)
	}
	if task.CreatedAt.IsZero() || task.NextClaimableAt.IsZero() {
		t.Fatalf("task times not set: %+v", task)
	}

	// Same requestId, same duration -> 200 with the first result.
	repeat := createTask(t, h, "dev-1", taskBody("req-1", 30), http.StatusOK)
	if repeat.ID != task.ID || !repeat.CreatedAt.Equal(task.CreatedAt) {
		t.Fatalf("repeat returned a different task: %+v vs %+v", repeat, task)
	}

	// Same requestId, different duration -> 409.
	createTask(t, h, "dev-1", taskBody("req-1", 45), http.StatusConflict)

	// Validation.
	createTask(t, h, "dev-1", `{"requestId":"  ","durationSeconds":10}`, http.StatusBadRequest)
	createTask(t, h, "dev-1", `{"requestId":"req-2"}`, http.StatusBadRequest)
	createTask(t, h, "dev-1", taskBody("req-3", 0), http.StatusBadRequest)
	createTask(t, h, "dev-1", taskBody("req-4", 61), http.StatusBadRequest)
	createTask(t, h, "dev-1", `{"requestId":"req-5","durationSeconds":"10"}`, http.StatusBadRequest)
	createTask(t, h, "dev-1", `{"requestId":"req-6","durationSeconds":1.5}`, http.StatusBadRequest)

	// Unknown device.
	createTask(t, h, "missing", taskBody("req-7", 10), http.StatusNotFound)
}

func TestTaskClaimAndReportSuccess(t *testing.T) {
	store, clock := newClockStore()
	h := NewHandler(store)
	mustRegister(t, h, "dev-1")
	createTask(t, h, "dev-1", taskBody("req-1", 30), http.StatusCreated)

	claim := claimTask(t, h, "dev-1", http.StatusOK)
	if claim.Attempt != 1 || claim.Credential == "" {
		t.Fatalf("unexpected claim: %+v", claim)
	}
	if !claim.Deadline.Equal(clock.UTC().Add(30 * time.Second)) {
		t.Fatalf("deadline = %s, want %s", claim.Deadline, clock.UTC().Add(30*time.Second))
	}
	if claim.Task.Status != "in_progress" || claim.Task.Attempts != 1 {
		t.Fatalf("claim task state: %+v", claim.Task)
	}

	// One task in progress at a time.
	claimTask(t, h, "dev-1", http.StatusNoContent)

	// Report success.
	report := reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-1", claim.Credential, true, "", `{"ok":true,"value":42}`), http.StatusCreated)
	if !report.Success || report.ReceiptID != "rcpt-1" {
		t.Fatalf("unexpected report: %+v", report)
	}

	task := getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
	if task.Status != "succeeded" || task.Result == nil || task.CompletedAt == nil {
		t.Fatalf("task after success: %+v", task)
	}

	// Same receiptId, same content -> 200 with the first result.
	reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-1", claim.Credential, true, "", `{"value":42,"ok":true}`), http.StatusOK)
	// Same receiptId, different content -> 409.
	reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-1", claim.Credential, true, "", `{"ok":false}`), http.StatusConflict)
	// Same receiptId, numeric value compared by value -> 200.
	reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-1", claim.Credential, true, "", `{"ok":true,"value":42.0}`), http.StatusOK)
	// Same receiptId, array order is significant -> 409.
	reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-1", claim.Credential, true, "", `{"ok":true,"value":[1,2]}`), http.StatusConflict)

	// A new receiptId with a stale credential -> 409.
	reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-2", claim.Credential, true, "", `{"ok":true}`), http.StatusConflict)
}

func TestTaskReportFailureAndBackoff(t *testing.T) {
	store, clock := newClockStore()
	h := NewHandler(store)
	mustRegister(t, h, "dev-1")
	createTask(t, h, "dev-1", taskBody("req-1", 30), http.StatusCreated)

	// First failure.
	claim := claimTask(t, h, "dev-1", http.StatusOK)
	reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-1", claim.Credential, false, "disk full", ""), http.StatusCreated)
	task := getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
	if task.Status != "waiting" || task.FailureReason != "disk full" || task.Attempts != 1 {
		t.Fatalf("after first failure: %+v", task)
	}
	if !task.NextClaimableAt.Equal(clock.UTC().Add(1 * time.Second)) {
		t.Fatalf("next claimable = %s, want +1s", task.NextClaimableAt)
	}
	claimTask(t, h, "dev-1", http.StatusNoContent)

	// After the backoff, claim again.
	*clock = clock.Add(2 * time.Second)
	claim = claimTask(t, h, "dev-1", http.StatusOK)
	if claim.Attempt != 2 {
		t.Fatalf("attempt = %d, want 2", claim.Attempt)
	}
	reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-2", claim.Credential, false, "still full", ""), http.StatusCreated)
	task = getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
	if task.Status != "waiting" || task.Attempts != 2 {
		t.Fatalf("after second failure: %+v", task)
	}
	if !task.NextClaimableAt.Equal(clock.UTC().Add(2 * time.Second)) {
		t.Fatalf("next claimable = %s, want +2s", task.NextClaimableAt)
	}

	// Third failure ends the task.
	*clock = clock.Add(3 * time.Second)
	claim = claimTask(t, h, "dev-1", http.StatusOK)
	if claim.Attempt != 3 {
		t.Fatalf("attempt = %d, want 3", claim.Attempt)
	}
	reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-3", claim.Credential, false, "gave up", ""), http.StatusCreated)
	task = getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
	if task.Status != "failed" || task.CompletedAt == nil {
		t.Fatalf("after third failure: %+v", task)
	}
	claimTask(t, h, "dev-1", http.StatusNoContent)
}

func TestTaskReportFailureRetry(t *testing.T) {
	store, clock := newClockStore()
	h := NewHandler(store)
	mustRegister(t, h, "dev-1")
	createTask(t, h, "dev-1", taskBody("req-1", 30), http.StatusCreated)

	claim := claimTask(t, h, "dev-1", http.StatusOK)
	first := reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-1", claim.Credential, false, "disk full", ""), http.StatusCreated)
	task := getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
	nextClaimable := task.NextClaimableAt

	// An identical retry is the received receipt again: 200 with the first
	// receiptId, reason and receive time.
	*clock = clock.Add(500 * time.Millisecond)
	retry := reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-1", claim.Credential, false, "disk full", ""), http.StatusOK)
	if retry.ReceiptID != first.ReceiptID || retry.Reason != first.Reason || !retry.ReceivedAt.Equal(first.ReceivedAt) {
		t.Fatalf("retry = %+v, want the first receipt %+v", retry, first)
	}

	// The retry does not accumulate a failure, re-time the wait or add audit.
	task = getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
	if task.Status != "waiting" || !task.NextClaimableAt.Equal(nextClaimable) {
		t.Fatalf("retry changed the task: %+v", task)
	}
	audit := listAudit(t, h, "dev-1", claim.Task.ID)
	if got := joinEvents(eventsOf(audit)); got != "created,claimed,failed" {
		t.Fatalf("audit after retry = %s", got)
	}

	// Same receiptId with a changed reason or flipped to success -> 409, and
	// the stored receipt is untouched.
	reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-1", claim.Credential, false, "other reason", ""), http.StatusConflict)
	reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-1", claim.Credential, true, "", `{"ok":true}`), http.StatusConflict)
	again := reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-1", claim.Credential, false, "disk full", ""), http.StatusOK)
	if !again.ReceivedAt.Equal(first.ReceivedAt) || again.Reason != "disk full" {
		t.Fatalf("receipt after conflicts = %+v", again)
	}

	// A new receiptId with the stale credential is rejected and does not take
	// the receiptId: the same receiptId is accepted once the task is claimed
	// again and reported with the fresh credential.
	reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-2", claim.Credential, false, "too early", ""), http.StatusConflict)

	// After the backoff the task is claimed again; the old receipt still
	// replays with the original (now stale) credential and neither the replay
	// nor a content conflict disturbs the running attempt.
	*clock = nextClaimable.Add(time.Second)
	claim2 := claimTask(t, h, "dev-1", http.StatusOK)
	if claim2.Attempt != 2 {
		t.Fatalf("re-claim attempt = %d, want 2", claim2.Attempt)
	}
	retry = reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-1", claim.Credential, false, "disk full", ""), http.StatusOK)
	if !retry.ReceivedAt.Equal(first.ReceivedAt) {
		t.Fatalf("retry after re-claim = %+v, want receivedAt %s", retry, first.ReceivedAt)
	}
	reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-1", claim.Credential, false, "changed", ""), http.StatusConflict)
	task = getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
	if task.Status != "in_progress" || task.Attempts != 2 || task.Deadline == nil || !task.Deadline.Equal(claim2.Deadline) {
		t.Fatalf("running attempt disturbed: %+v", task)
	}

	// The device reports the new attempt's failure with a fresh receiptId and
	// the current credential; it joins the usual accumulation and backoff.
	reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-2", claim2.Credential, false, "still full", ""), http.StatusCreated)
	task = getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
	if task.Status != "waiting" || task.FailureReason != "still full" {
		t.Fatalf("after second failure: %+v", task)
	}
	if !task.NextClaimableAt.Equal(clock.UTC().Add(2 * time.Second)) {
		t.Fatalf("next claimable = %s, want +2s", task.NextClaimableAt)
	}
	audit = listAudit(t, h, "dev-1", claim.Task.ID)
	if got := joinEvents(eventsOf(audit)); got != "created,claimed,failed,claimed,failed" {
		t.Fatalf("audit = %s", got)
	}
}

// A diagnostic receiptId belongs to exactly one task of a device: once task 1
// has accepted it, task 2 of the same device cannot take it as a new receipt,
// even with identical content, its own valid credential and time left. The
// rejected submission leaves task 2's execution untouched; an unused number
// still works, the original receipt still replays on task 1, and another
// device accepts the same number independently.
func TestTaskReceiptBoundToOneTask(t *testing.T) {
	store, _ := newClockStore()
	h := NewHandler(store)
	mustRegister(t, h, "dev-1")
	mustRegister(t, h, "dev-2")
	createTask(t, h, "dev-1", taskBody("req-1", 30), http.StatusCreated)
	claim1 := claimTask(t, h, "dev-1", http.StatusOK)
	first := reportTask(t, h, "dev-1", claim1.Task.ID,
		reportBody("shared-rcpt", claim1.Credential, true, "", `{"ok":true,"n":1}`), http.StatusCreated)

	// Task 2 is claimed next and is still in progress within its deadline with
	// its own credential.
	createTask(t, h, "dev-1", taskBody("req-2", 30), http.StatusCreated)
	claim2 := claimTask(t, h, "dev-1", http.StatusOK)
	if claim2.Task.ID != 2 {
		t.Fatalf("second claim took task %d, want 2", claim2.Task.ID)
	}

	// Reusing task 1's receipt on task 2 conflicts with identical content...
	reportTask(t, h, "dev-1", 2,
		reportBody("shared-rcpt", claim2.Credential, true, "", `{"n":1,"ok":true}`), http.StatusConflict)
	// ...and with different content just the same.
	reportTask(t, h, "dev-1", 2,
		reportBody("shared-rcpt", claim2.Credential, true, "", `{"ok":false}`), http.StatusConflict)

	// Task 2 keeps its previous execution state, attempts, deadline and
	// credential, and gains no completion or failure audit record.
	task2 := getTask(t, h, "dev-1", 2, http.StatusOK)
	if task2.Status != "in_progress" || task2.Attempts != 1 || task2.CompletedAt != nil {
		t.Fatalf("conflict disturbed task 2 state: %+v", task2)
	}
	if task2.Deadline == nil || !task2.Deadline.Equal(claim2.Deadline) {
		t.Fatalf("task 2 deadline changed: %+v vs claim %s", task2.Deadline, claim2.Deadline)
	}
	if got := joinEvents(eventsOf(listAudit(t, h, "dev-1", 2))); got != "created,claimed" {
		t.Fatalf("task 2 audit after conflict = %s, want created,claimed", got)
	}

	// An unused receiptId succeeds on the still-valid execution.
	reportTask(t, h, "dev-1", 2,
		reportBody("rcpt-2", claim2.Credential, true, "", `{"ok":true}`), http.StatusCreated)
	task2 = getTask(t, h, "dev-1", 2, http.StatusOK)
	if task2.Status != "succeeded" || task2.CompletedAt == nil {
		t.Fatalf("task 2 after fresh receipt: %+v", task2)
	}
	if got := joinEvents(eventsOf(listAudit(t, h, "dev-1", 2))); got != "created,claimed,succeeded" {
		t.Fatalf("task 2 audit = %s", got)
	}

	// Task 1 gained nothing from the conflict.
	if got := joinEvents(eventsOf(listAudit(t, h, "dev-1", 1))); got != "created,claimed,succeeded" {
		t.Fatalf("task 1 audit = %s", got)
	}
	// The original receipt keeps replaying on task 1 with the first receive
	// time; numeric spelling differences are not content changes.
	retry := reportTask(t, h, "dev-1", 1,
		reportBody("shared-rcpt", claim1.Credential, true, "", `{"ok":true,"n":1.0}`), http.StatusOK)
	if !retry.ReceivedAt.Equal(first.ReceivedAt) {
		t.Fatalf("retry receivedAt = %s, want %s", retry.ReceivedAt, first.ReceivedAt)
	}

	// Another device accepts the same number independently.
	createTask(t, h, "dev-2", taskBody("req-a", 30), http.StatusCreated)
	claimOther := claimTask(t, h, "dev-2", http.StatusOK)
	reportTask(t, h, "dev-2", claimOther.Task.ID,
		reportBody("shared-rcpt", claimOther.Credential, true, "", `{"ok":true}`), http.StatusCreated)
}

